  + Name : string
  + StockLevel : int
}

class Order {
  + OrderDate : date
  + PaymentDate : date
  + IsPaid : boolean
}

class OrderLine {
  + Quantity : int
  + IsShipped : boolean
}

class Invoice {
  + InvoiceDate : date
}

class Delivery {
  + Status : string
  + PackingDate : date
  + ShippingDate : date
  + ReceivedDate : date
}

class DeliveryLine {
}

class Warehouse {
  + Address : string
}

class Supermarket {
  + Name : string
}

Customer "1" -- "*" Order : places
Order "1" *-- "1..*" OrderLine : contains
OrderLine "1" -- "*" DeliveryLine : partOf
Delivery "1" *-- "1..*" DeliveryLine : contains
Delivery "1" -- "1" Order : fulfills
Order "*" -- "0..1" Invoice : billedBy
Customer "1" -- "*" Invoice : receives
Customer "1" -- "*" Warehouse : uses
Warehouse "*" -- "1" Supermarket : belongsTo
Supermarket "1" -- "*" Warehouse : has
Order "*" -- "1" Supermarket : deliveredTo
OrderLine "*" -- "1" Product : refersTo
DeliveryLine "*" -- "1" Product : contains

@enduml

